    ) VALUES (
      175, 'Tyler Holt Cable Torso Twist', 'Tyler Holt Cable Torso Twist', 'تمرين دوران الجذع والخواصر بالكيبل',
      'Master guide and execution tutorial for Tyler Holt Cable Torso Twist.', 'Master guide and execution tutorial for Tyler Holt Cable Torso Twist.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين دوران الجذع والخواصر بالكيبل.',
      '["Setup: Position yourself with spine supported, abdominal wall drawn in, and neck relaxed in neutral alignment","Movement: Contract your core to perform the movement or maintain a rock-solid isometric brace","Breathing: Maintain steady, rhythmic breathing without holding your breath","Control: Move with deliberate tempo, avoiding reliance on momentum or neck straining"]', '["اتخذ وضعية الانطلاق الصحيحة لتمرين تمرين دوران الجذع والخواصر بالكيبل مع شد عضلات الكور.","قم بالحركة بالمدى الحركي الكامل وبتحكم وسيطرة تامة على المسار.","توقف في قمة الانقباض لتركيز الجهد على العضلة المستهدفة مع الزفير.","عد ببطء إلى نقطة البداية مع الحفاظ على استقامة العمود الفقري."]', 'Abs',
      'عضلات البطن والكور', 'Abs', 'Cable',
      'كيبل', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/abs-crunch.gif', 'https://musclewiki.com/media/uploads/abs-crunch.gif',
      'https://musclewiki.com/media/uploads/abs-crunch.gif', 'https://www.youtube.com/results?search_query=Tyler%20Holt%20Cable%20Torso%20Twist%20tutorial%20form', 'https://www.youtube.com/results?search_query=Tyler%20Holt%20Cable%20Torso%20Twist%20tutorial%20form',
      '', '["Obliques"," Hip Flexors"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
      "name" = EXCLUDED."name",
      "name_en" = EXCLUDED."name_en",
      "name_ar" = EXCLUDED."name_ar",
      "description_en" = EXCLUDED."description_en",
