    ) VALUES (
      480, 'Holman Boat Press with Leg Extension', 'Holman Boat Press with Leg Extension', 'فرد أرجل أمامي بالجهاز',
      'Master guide and execution tutorial for Holman Boat Press with Leg Extension.', 'Master guide and execution tutorial for Holman Boat Press with Leg Extension.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين فرد أرجل أمامي بالجهاز.',
      '["Setup: Position yourself with spine supported, abdominal wall drawn in, and neck relaxed in neutral alignment","Movement: Contract your core to perform the movement or maintain a rock-solid isometric brace","Breathing: Maintain steady, rhythmic breathing without holding your breath","Control: Move with deliberate tempo, avoiding reliance on momentum or neck straining"]', '["اتخذ وضعية الانطلاق الصحيحة لتمرين فرد أرجل أمامي بالجهاز مع شد عضلات الكور.","قم بالحركة بالمدى الحركي الكامل وبتحكم وسيطرة تامة على المسار.","توقف في قمة الانقباض لتركيز الجهد على العضلة المستهدفة مع الزفير.","عد ببطء إلى نقطة البداية مع الحفاظ على استقامة العمود الفقري."]', 'Abs',
      'عضلات البطن والكور', 'Abs', 'Body only',
      'أدوات الجيم', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/abs-crunch.gif', 'https://musclewiki.com/media/uploads/abs-crunch.gif',
      'https://musclewiki.com/media/uploads/abs-crunch.gif', 'https://www.youtube.com/results?search_query=Holman%20Boat%20Press%20with%20Leg%20Extension%20tutorial%20form', 'https://www.youtube.com/results?search_query=Holman%20Boat%20Press%20with%20Leg%20Extension%20tutorial%20form',
      '', '["Obliques"," Hip Flexors"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
      "name" = EXCLUDED."name",
      "name_en" = EXCLUDED."name_en",
      "name_ar" = EXCLUDED."name_ar",
      "description_en" = EXCLUDED."description_en",
