    ) VALUES (
      978, 'One-Arm Push-Up', 'One-Arm Push-Up', 'تمرين الضغط (بوش اب) بذراع واحدة',
      'Master guide and execution tutorial for One-Arm Push-Up.', 'Master guide and execution tutorial for One-Arm Push-Up.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين الضغط (بوش اب) بذراع واحدة.',
      '["Setup: Lie back or stand securely with your core engaged, feet firmly planted, and grip the Body only at shoulder width","Execution: Inhale and lower the weight in a controlled motion until your elbows reach approximately 90 degrees or a comfortable full stretch","Contraction: Exhale and press the weight upward focusing on contracting the Chest, without locking out elbows abruptly","Recovery: Pause briefly at peak contraction before repeating for target repetitions"]', '["اتخذ وضعية البداية الصحيحة لـ تمرين الضغط (بوش اب) بذراع واحدة مع تثبيت القدمين وسحب لوحي الكتف للخلف.","أمسك بالوزن بقبضة محكمة وثبت المرفقين بزاوية 45 درجة لحماية مفصل الكتف.","ادفع المقاومة للأمام/للأعلى مع التركيز على عصر عضلات الصدر عند قمة الحركة مع الزفير.","انزل بالوزن ببطء وتحكم كامل خلال 2-3 ثوانٍ حتى تشعر بتمدد ألياف الصدر مع أخذ الشهيق."]', 'Chest',
      'الصدر', 'Chest', 'Body only',
      'أدوات الجيم', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/chest-barbell-bench-press.gif', 'https://musclewiki.com/media/uploads/chest-barbell-bench-press.gif',
      'https://musclewiki.com/media/uploads/chest-barbell-bench-press.gif', 'https://www.youtube.com/results?search_query=One-Arm%20Push-Up%20tutorial%20form', 'https://www.youtube.com/results?search_query=One-Arm%20Push-Up%20tutorial%20form',
      '', '["Triceps Brachii"," Anterior Deltoids"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
      "name" = EXCLUDED."name",
      "name_en" = EXCLUDED."name_en",
      "name_ar" = EXCLUDED."name_ar",
      "description_en" = EXCLUDED."description_en",
