    ) VALUES (
      984, 'Swimming', 'Swimming', 'تمرين الصدر',
      'Master guide and execution tutorial for Swimming.', 'Master guide and execution tutorial for Swimming.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين الصدر.',
      '["Setup: Begin in a ready athletic stance, core braced, and breathing rhythmically","Execution: Perform dynamic, coordinated movements maintaining steady cadence and good posture","Landing: Land softly on the balls of your feet to absorb impact smoothly","Pacing: Keep an elevated heart rate while maintaining controlled breathing and full range of motion"]', '["اتخذ وضعية البداية الصحيحة لـ تمرين الصدر مع تثبيت القدمين وسحب لوحي الكتف للخلف.","أمسك بالوزن بقبضة محكمة وثبت المرفقين بزاوية 45 درجة لحماية مفصل الكتف.","ادفع المقاومة للأمام/للأعلى مع التركيز على عصر عضلات الصدر عند قمة الحركة مع الزفير.","انزل بالوزن ببطء وتحكم كامل خلال 2-3 ثوانٍ حتى تشعر بتمدد ألياف الصدر مع أخذ الشهيق."]', 'Chest',
      'الصدر', 'Chest', 'Body only',
      'أدوات الجيم', 'Beginner', 'CARDIO',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/chest-barbell-bench-press.gif', 'https://musclewiki.com/media/uploads/chest-barbell-bench-press.gif',
      'https://musclewiki.com/media/uploads/chest-barbell-bench-press.gif', 'https://www.youtube.com/results?search_query=Swimming%20tutorial%20form', 'https://www.youtube.com/results?search_query=Swimming%20tutorial%20form',
      '', '["Triceps Brachii"," Anterior Deltoids"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
