    ) VALUES (
      1103, 'Single-arm kettlebell row', 'Single-arm kettlebell row', 'تجديف للظهر (رو) بذراع واحدة بالدمبلز',
      'Master guide and execution tutorial for Single-arm kettlebell row.', 'Master guide and execution tutorial for Single-arm kettlebell row.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تجديف للظهر (رو) بذراع واحدة بالدمبلز.',
      '["Setup: Position yourself with chest proud, shoulder blades retracted and depressed, gripping the Dumbbell firmly","Execution: Initiate the movement by pulling with your back and driving your elbows down and back toward your torso","Contraction: Squeeze your shoulder blades together at the peak of the movement, exhaling during the contraction","Recovery: Inhale and allow your arms and lats to stretch forward/upward in a slow, controlled eccentric return"]', '["اتخذ وضعية البداية الصحيحة لـ تجديف للظهر (رو) بذراع واحدة بالدمبلز مع تثبيت القدمين وسحب لوحي الكتف للخلف.","أمسك بالوزن بقبضة محكمة وثبت المرفقين بزاوية 45 درجة لحماية مفصل الكتف.","ادفع المقاومة للأمام/للأعلى مع التركيز على عصر عضلات الصدر عند قمة الحركة مع الزفير.","انزل بالوزن ببطء وتحكم كامل خلال 2-3 ثوانٍ حتى تشعر بتمدد ألياف الصدر مع أخذ الشهيق."]', 'Chest',
      'الصدر', 'Chest', 'Dumbbell',
      'دمبلز', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/chest-barbell-bench-press.gif', 'https://musclewiki.com/media/uploads/chest-barbell-bench-press.gif',
      'https://musclewiki.com/media/uploads/chest-barbell-bench-press.gif', 'https://www.youtube.com/results?search_query=Single-arm%20kettlebell%20row%20tutorial%20form', 'https://www.youtube.com/results?search_query=Single-arm%20kettlebell%20row%20tutorial%20form',
      '', '["Triceps Brachii"," Anterior Deltoids"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
