    ) VALUES (
      1222, 'Single Leg Glute Bridge', 'Single Leg Glute Bridge', 'جسر الأرداف (جلوت بريدج) برجل واحدة',
      'Master guide and execution tutorial for Single Leg Glute Bridge.', 'Master guide and execution tutorial for Single Leg Glute Bridge.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين جسر الأرداف (جلوت بريدج) برجل واحدة.',
      '["Lay on the floor with your feet flat and knees bent.","Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.","Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.","Extend as far as possible, pause and then return to the starting position."]', '["قف مع مباعدة القدمين باتساع مناسب وثبّت الكعبين على الأرض لأداء جسر الأرداف (جلوت بريدج) برجل واحدة.","انزل بالحوض للأسفل والخلف مع الحفاظ على استقامة الظهر وعضلات البطن مشدودة.","ادفع الأرض بقوة عبر باطن القدم للعودة للأعلى مع الزفير وعصر عضلات الفخذ والأرداف.","كرر الحركة بتحكم وسلاسة وتجنب قفل مفاصل الركبة بعنف في قمة الحركة."]', 'Hamstrings',
      'الفخذ الخلفي والأرداف', 'Hamstrings', 'body only',
      'أدوات الجيم', 'Beginner', 'strength',
      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Single%20Leg%20Glute%20Bridge%20tutorial%20form', 'https://www.youtube.com/results?search_query=Single%20Leg%20Glute%20Bridge%20tutorial%20form',
      '', '["hamstrings"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
