    ) VALUES (
      1251, 'HM Left Side Iron Cross', 'HM Left Side Iron Cross', 'تمرين الفخذ الخلفي والأرداف',
      'Master guide and execution tutorial for HM Left Side Iron Cross.', 'Master guide and execution tutorial for HM Left Side Iron Cross.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين الفخذ الخلفي والأرداف.',
      '["Setup: Position yourself with proper posture, core braced, and secure grip on the Body only","Execution: Inhale and initiate the exercise with controlled tempo, focusing on the Glutes","Peak: Contract firmly at maximum range of motion with full muscle engagement","Return: Exhale and return steadily to the starting position"]', '["قف مع مباعدة القدمين باتساع مناسب وثبّت الكعبين على الأرض لأداء تمرين الفخذ الخلفي والأرداف.","انزل بالحوض للأسفل والخلف مع الحفاظ على استقامة الظهر وعضلات البطن مشدودة.","ادفع الأرض بقوة عبر باطن القدم للعودة للأعلى مع الزفير وعصر عضلات الفخذ والأرداف.","كرر الحركة بتحكم وسلاسة وتجنب قفل مفاصل الركبة بعنف في قمة الحركة."]', 'Hamstrings',
      'الفخذ الخلفي والأرداف', 'Hamstrings', 'Body only',
      'أدوات الجيم', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/glutes-barbell-hip-thrust.gif', 'https://musclewiki.com/media/uploads/glutes-barbell-hip-thrust.gif',
      'https://musclewiki.com/media/uploads/glutes-barbell-hip-thrust.gif', 'https://www.youtube.com/results?search_query=HM%20Left%20Side%20Iron%20Cross%20tutorial%20form', 'https://www.youtube.com/results?search_query=HM%20Left%20Side%20Iron%20Cross%20tutorial%20form',
      '', '["Lower Back"," Calves"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
      "name" = EXCLUDED."name",
      "name_en" = EXCLUDED."name_en",
      "name_ar" = EXCLUDED."name_ar",
