    ) VALUES (
      1257, 'UN Glute Bridge', 'UN Glute Bridge', 'جسر الأرداف (جلوت بريدج)',
      'Master guide and execution tutorial for UN Glute Bridge.', 'Master guide and execution tutorial for UN Glute Bridge.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين جسر الأرداف (جلوت بريدج).',
      '["Setup: Stand tall with a slight micro-bend in your knees, holding the Body only with a firm grip","Hinge: Push your hips backward as if touching a wall behind you, keeping your back flat and spine neutral","Stretch: Lower the weight along your shins until you feel a deep stretch in your hamstrings and glutes","Drive: Squeeze your glutes and drive your hips forward to return to standing, exhaling at the top"]', '["قف مع مباعدة القدمين باتساع مناسب وثبّت الكعبين على الأرض لأداء جسر الأرداف (جلوت بريدج).","انزل بالحوض للأسفل والخلف مع الحفاظ على استقامة الظهر وعضلات البطن مشدودة.","ادفع الأرض بقوة عبر باطن القدم للعودة للأعلى مع الزفير وعصر عضلات الفخذ والأرداف.","كرر الحركة بتحكم وسلاسة وتجنب قفل مفاصل الركبة بعنف في قمة الحركة."]', 'Hamstrings',
      'الفخذ الخلفي والأرداف', 'Hamstrings', 'Body only',
      'أدوات الجيم', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/glutes-barbell-hip-thrust.gif', 'https://musclewiki.com/media/uploads/glutes-barbell-hip-thrust.gif',
      'https://musclewiki.com/media/uploads/glutes-barbell-hip-thrust.gif', 'https://www.youtube.com/results?search_query=UN%20Glute%20Bridge%20tutorial%20form', 'https://www.youtube.com/results?search_query=UN%20Glute%20Bridge%20tutorial%20form',
      '', '["Lower Back"," Calves"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
