    ) VALUES (
      1564, 'FYR2 Dumbbell Deadlift', 'FYR2 Dumbbell Deadlift', 'ديدليفت (رفعة ميتة) بالدمبلز',
      'Master guide and execution tutorial for FYR2 Dumbbell Deadlift.', 'Master guide and execution tutorial for FYR2 Dumbbell Deadlift.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين ديدليفت (رفعة ميتة) بالدمبلز.',
      '["Setup: Stand tall with a slight micro-bend in your knees, holding the Dumbbell with a firm grip","Hinge: Push your hips backward as if touching a wall behind you, keeping your back flat and spine neutral","Stretch: Lower the weight along your shins until you feel a deep stretch in your hamstrings and glutes","Drive: Squeeze your glutes and drive your hips forward to return to standing, exhaling at the top"]', '["ثبّت الصدر للأمام والظهر مستقيماً لبدء ديدليفت (رفعة ميتة) بالدمبلز بثبات تام للحوض.","ابدأ حركة السحب بقيادة الكوعين للخلف باتجاه الخصر وليس بسحب المعصم.","اعصر عضلات الظهر بقوة لمدة ثانية في ذروة الانقباض العضلي مع الزفير.","أعد المقاومة ببطء إلى وضعية البداية مع تمديد عضلات الظهر تدريجياً دون تقويس العمود الفقري."]', 'Back',
      'الظهر', 'Back', 'Dumbbell',
      'دمبلز', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/back-hyperextension.gif', 'https://musclewiki.com/media/uploads/back-hyperextension.gif',
      'https://musclewiki.com/media/uploads/back-hyperextension.gif', 'https://www.youtube.com/results?search_query=FYR2%20Dumbbell%20Deadlift%20tutorial%20form', 'https://www.youtube.com/results?search_query=FYR2%20Dumbbell%20Deadlift%20tutorial%20form',
      '', '["Biceps Brachii"," Rear Deltoids"," Forearms"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
