    ) VALUES (
      1651, 'Kettlebell bent-over row to clean', 'Kettlebell bent-over row to clean', 'تجديف منحني للظهر بالكتلبل',
      'Master guide and execution tutorial for Kettlebell bent-over row to clean.', 'Master guide and execution tutorial for Kettlebell bent-over row to clean.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تجديف منحني للظهر بالكتلبل.',
      '["Setup: Position yourself with chest proud, shoulder blades retracted and depressed, gripping the Kettlebells firmly","Execution: Initiate the movement by pulling with your back and driving your elbows down and back toward your torso","Contraction: Squeeze your shoulder blades together at the peak of the movement, exhaling during the contraction","Recovery: Inhale and allow your arms and lats to stretch forward/upward in a slow, controlled eccentric return"]', '["ثبّت الصدر للأمام والظهر مستقيماً لبدء تجديف منحني للظهر بالكتلبل بثبات تام للحوض.","ابدأ حركة السحب بقيادة الكوعين للخلف باتجاه الخصر وليس بسحب المعصم.","اعصر عضلات الظهر بقوة لمدة ثانية في ذروة الانقباض العضلي مع الزفير.","أعد المقاومة ببطء إلى وضعية البداية مع تمديد عضلات الظهر تدريجياً دون تقويس العمود الفقري."]', 'Back',
      'الظهر', 'Back', 'Kettlebell',
      'كتلبل', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/back-barbell-row.gif', 'https://musclewiki.com/media/uploads/back-barbell-row.gif',
      'https://musclewiki.com/media/uploads/back-barbell-row.gif', 'https://www.youtube.com/results?search_query=Kettlebell%20bent-over%20row%20to%20clean%20tutorial%20form', 'https://www.youtube.com/results?search_query=Kettlebell%20bent-over%20row%20to%20clean%20tutorial%20form',
      '', '["Biceps Brachii"," Rear Deltoids"," Forearms"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
