    ) VALUES (
      1766, 'Scapular Pull-Up', 'Scapular Pull-Up', 'سحب عقلة (قبضة علوية)',
      'Master guide and execution tutorial for Scapular Pull-Up.', 'Master guide and execution tutorial for Scapular Pull-Up.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين سحب عقلة (قبضة علوية).',
      '["Setup: Position yourself with chest proud, shoulder blades retracted and depressed, gripping the Body only firmly","Execution: Initiate the movement by pulling with your back and driving your elbows down and back toward your torso","Contraction: Squeeze your shoulder blades together at the peak of the movement, exhaling during the contraction","Recovery: Inhale and allow your arms and lats to stretch forward/upward in a slow, controlled eccentric return"]', '["اتخذ وضعية الانطلاق الصحيحة لتمرين سحب عقلة (قبضة علوية) مع شد عضلات الكور.","قم بالحركة بالمدى الحركي الكامل وبتحكم وسيطرة تامة على المسار.","توقف في قمة الانقباض لتركيز الجهد على العضلة المستهدفة مع الزفير.","عد ببطء إلى نقطة البداية مع الحفاظ على استقامة العمود الفقري."]', 'Full Body',
      'كامل الجسم', 'Full Body', 'Body only',
      'أدوات الجيم', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/master/exercises/Scapular_Pull-Up/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/master/exercises/Scapular_Pull-Up/0.jpg',
      'https://raw.githubusercontent.com/yuhonas/free-exercise-db/master/exercises/Scapular_Pull-Up/0.jpg', 'https://www.youtube.com/results?search_query=Scapular%20Pull-Up%20tutorial%20form', 'https://www.youtube.com/results?search_query=Scapular%20Pull-Up%20tutorial%20form',
      '', '["Triceps Brachii"," Upper Chest"," Trapezius"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
