    ) VALUES (
      1878, 'HM Single-Leg Romanian Deadlift', 'HM Single-Leg Romanian Deadlift', 'ديدليفت روماني (أرجل خلفية) برجل واحدة',
      'Master guide and execution tutorial for HM Single-Leg Romanian Deadlift.', 'Master guide and execution tutorial for HM Single-Leg Romanian Deadlift.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين ديدليفت روماني (أرجل خلفية) برجل واحدة.',
      '["Setup: Stand tall with a slight micro-bend in your knees, holding the Kettlebells with a firm grip","Hinge: Push your hips backward as if touching a wall behind you, keeping your back flat and spine neutral","Stretch: Lower the weight along your shins until you feel a deep stretch in your hamstrings and glutes","Drive: Squeeze your glutes and drive your hips forward to return to standing, exhaling at the top"]', '["قف مع مباعدة القدمين باتساع مناسب وثبّت الكعبين على الأرض لأداء ديدليفت روماني (أرجل خلفية) برجل واحدة.","انزل بالحوض للأسفل والخلف مع الحفاظ على استقامة الظهر وعضلات البطن مشدودة.","ادفع الأرض بقوة عبر باطن القدم للعودة للأعلى مع الزفير وعصر عضلات الفخذ والأرداف.","كرر الحركة بتحكم وسلاسة وتجنب قفل مفاصل الركبة بعنف في قمة الحركة."]', 'Quadriceps',
      'الفخذ الأمامي (الكوادس)', 'Quadriceps', 'Kettlebell',
      'كتلبل', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/quads-barbell-squat.gif', 'https://musclewiki.com/media/uploads/quads-barbell-squat.gif',
      'https://musclewiki.com/media/uploads/quads-barbell-squat.gif', 'https://www.youtube.com/results?search_query=HM%20Single-Leg%20Romanian%20Deadlift%20tutorial%20form', 'https://www.youtube.com/results?search_query=HM%20Single-Leg%20Romanian%20Deadlift%20tutorial%20form',
      '', '["Gluteus Maximus"," Hamstrings"," Calves"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
