      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Backward_Drag/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Backward_Drag/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Backward%20Drag%20tutorial%20form', 'https://www.youtube.com/results?search_query=Backward%20Drag%20tutorial%20form',
