    ) VALUES (
      2049, 'Stair climber', 'Stair climber', 'تمرين الفخذ الأمامي (الكوادس) بالجهاز',
      'Master guide and execution tutorial for Stair climber.', 'Master guide and execution tutorial for Stair climber.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين الفخذ الأمامي (الكوادس) بالجهاز.',
      '["Setup: Begin in a ready athletic stance, core braced, and breathing rhythmically","Execution: Perform dynamic, coordinated movements maintaining steady cadence and good posture","Landing: Land softly on the balls of your feet to absorb impact smoothly","Pacing: Keep an elevated heart rate while maintaining controlled breathing and full range of motion"]', '["قف مع مباعدة القدمين باتساع مناسب وثبّت الكعبين على الأرض لأداء تمرين الفخذ الأمامي (الكوادس) بالجهاز.","انزل بالحوض للأسفل والخلف مع الحفاظ على استقامة الظهر وعضلات البطن مشدودة.","ادفع الأرض بقوة عبر باطن القدم للعودة للأعلى مع الزفير وعصر عضلات الفخذ والأرداف.","كرر الحركة بتحكم وسلاسة وتجنب قفل مفاصل الركبة بعنف في قمة الحركة."]', 'Quadriceps',
      'الفخذ الأمامي (الكوادس)', 'Quadriceps', 'Machine',
      'جهاز', 'Beginner', 'CARDIO',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/quads-barbell-squat.gif', 'https://musclewiki.com/media/uploads/quads-barbell-squat.gif',
      'https://musclewiki.com/media/uploads/quads-barbell-squat.gif', 'https://www.youtube.com/results?search_query=Stair%20climber%20tutorial%20form', 'https://www.youtube.com/results?search_query=Stair%20climber%20tutorial%20form',
      '', '["Gluteus Maximus"," Hamstrings"," Calves"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
