    ) VALUES (
      2205, 'HM Sumo Squat', 'HM Sumo Squat', 'سومو سكوات',
      'Master guide and execution tutorial for HM Sumo Squat.', 'Master guide and execution tutorial for HM Sumo Squat.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين سومو سكوات.',
      '["Setup: Stand with feet shoulder-width apart, toes slightly turned out, core braced, and chest elevated","Execution: Inhale and initiate the descent by breaking at your hips and knees simultaneously, lowering your hips until thighs are parallel to the floor","Drive: Exhale and drive firmly through your mid-foot and heels to return to the starting upright position","Alignment: Keep your knees tracking in line with your toes throughout the entire rep"]', '["قف مع مباعدة القدمين باتساع مناسب وثبّت الكعبين على الأرض لأداء سومو سكوات.","انزل بالحوض للأسفل والخلف مع الحفاظ على استقامة الظهر وعضلات البطن مشدودة.","ادفع الأرض بقوة عبر باطن القدم للعودة للأعلى مع الزفير وعصر عضلات الفخذ والأرداف.","كرر الحركة بتحكم وسلاسة وتجنب قفل مفاصل الركبة بعنف في قمة الحركة."]', 'Quadriceps',
      'الفخذ الأمامي (الكوادس)', 'Quadriceps', 'Body only',
      'أدوات الجيم', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/quads-barbell-squat.gif', 'https://musclewiki.com/media/uploads/quads-barbell-squat.gif',
      'https://musclewiki.com/media/uploads/quads-barbell-squat.gif', 'https://www.youtube.com/results?search_query=HM%20Sumo%20Squat%20tutorial%20form', 'https://www.youtube.com/results?search_query=HM%20Sumo%20Squat%20tutorial%20form',
      '', '["Gluteus Maximus"," Hamstrings"," Calves"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
