    ) VALUES (
      2448, 'Jerk Balance', 'Jerk Balance', 'تمرين الأكتاف بالبار',
      'Master guide and execution tutorial for Jerk Balance.', 'Master guide and execution tutorial for Jerk Balance.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين الأكتاف بالبار.',
      '["This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart.","Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight.","Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight. Recover by standing up with the weight overhead."]', '["قف أو اجلس باستقامة تامة مع شد عضلات الجذع لتنفيذ تمرين الأكتاف بالبار.","ارفع المقاومة بالمسار المخصص مع إبقاء الأكتاف منخفضة وبعيدة عن الرقبة.","توقف لجزء من الثانية في قمة الحركة لعزل الرأس المستهدف من الدالية.","انزل ببطء وتحكم كامل مع الحفاظ على التوتر العضلي طوال المسار السلبي."]', 'Shoulders',
      'الأكتاف', 'Shoulders', 'Barbell',
      'بار', 'Beginner', 'olympic weightlifting',
      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jerk_Balance/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jerk_Balance/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Jerk%20Balance%20tutorial%20form', 'https://www.youtube.com/results?search_query=Jerk%20Balance%20tutorial%20form',
      '', '["glutes","hamstrings","quadriceps","triceps"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
