    ) VALUES (
      2454, 'Single-arm barbell lateral raise', 'Single-arm barbell lateral raise', 'رفرفة كتف جانبي بذراع واحدة بالبار',
      'Master guide and execution tutorial for Single-arm barbell lateral raise.', 'Master guide and execution tutorial for Single-arm barbell lateral raise.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين رفرفة كتف جانبي بذراع واحدة بالبار.',
      '["Setup: Maintain a slight elbow bend, engage your core, and position the Barbell at shoulder level","Fly: Move your arms in a wide arcing motion, bringing the weights together while focusing on squeezing the Shoulders","Peak: Contract firmly at the apex of the arc without clashing the weights","Stretch: Inhale and open arms back along the same wide arc until you feel a comfortable deep stretch"]', '["قف أو اجلس باستقامة تامة مع شد عضلات الجذع لتنفيذ رفرفة كتف جانبي بذراع واحدة بالبار.","ارفع المقاومة بالمسار المخصص مع إبقاء الأكتاف منخفضة وبعيدة عن الرقبة.","توقف لجزء من الثانية في قمة الحركة لعزل الرأس المستهدف من الدالية.","انزل ببطء وتحكم كامل مع الحفاظ على التوتر العضلي طوال المسار السلبي."]', 'Shoulders',
      'الأكتاف', 'Shoulders', 'Barbell',
      'بار', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/shoulders-dumbbells-overhead-press.gif', 'https://musclewiki.com/media/uploads/shoulders-dumbbells-overhead-press.gif',
      'https://musclewiki.com/media/uploads/shoulders-dumbbells-overhead-press.gif', 'https://www.youtube.com/results?search_query=Single-arm%20barbell%20lateral%20raise%20tutorial%20form', 'https://www.youtube.com/results?search_query=Single-arm%20barbell%20lateral%20raise%20tutorial%20form',
      '', '["Triceps Brachii"," Upper Chest"," Trapezius"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
