    ) VALUES (
      2477, 'Kettlebell Arnold Press', 'Kettlebell Arnold Press', 'أرنولد برس للأكتاف بالكتلبل',
      'Master guide and execution tutorial for Kettlebell Arnold Press.', 'Master guide and execution tutorial for Kettlebell Arnold Press.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين أرنولد برس للأكتاف بالكتلبل.',
      '["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward.","Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion.","Return the kettlebell to the starting position, with the palm facing in."]', '["قف أو اجلس باستقامة تامة مع شد عضلات الجذع لتنفيذ أرنولد برس للأكتاف بالكتلبل.","ارفع المقاومة بالمسار المخصص مع إبقاء الأكتاف منخفضة وبعيدة عن الرقبة.","توقف لجزء من الثانية في قمة الحركة لعزل الرأس المستهدف من الدالية.","انزل ببطء وتحكم كامل مع الحفاظ على التوتر العضلي طوال المسار السلبي."]', 'Shoulders',
      'الأكتاف', 'Shoulders', 'Kettlebell',
      'كتلبل', 'Beginner', 'strength',
      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Arnold_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Arnold_Press/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Kettlebell%20Arnold%20Press%20tutorial%20form', 'https://www.youtube.com/results?search_query=Kettlebell%20Arnold%20Press%20tutorial%20form',
      '', '["triceps"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
