    ) VALUES (
      2621, 'RG Forward-Leaning Dumbbell Upright Row', 'RG Forward-Leaning Dumbbell Upright Row', 'تجديف للظهر (رو) بالدمبلز',
      'Master guide and execution tutorial for RG Forward-Leaning Dumbbell Upright Row.', 'Master guide and execution tutorial for RG Forward-Leaning Dumbbell Upright Row.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تجديف للظهر (رو) بالدمبلز.',
      '["Setup: Position yourself with chest proud, shoulder blades retracted and depressed, gripping the Dumbbell firmly","Execution: Initiate the movement by pulling with your back and driving your elbows down and back toward your torso","Contraction: Squeeze your shoulder blades together at the peak of the movement, exhaling during the contraction","Recovery: Inhale and allow your arms and lats to stretch forward/upward in a slow, controlled eccentric return"]', '["قف أو اجلس باستقامة تامة مع شد عضلات الجذع لتنفيذ تجديف للظهر (رو) بالدمبلز.","ارفع المقاومة بالمسار المخصص مع إبقاء الأكتاف منخفضة وبعيدة عن الرقبة.","توقف لجزء من الثانية في قمة الحركة لعزل الرأس المستهدف من الدالية.","انزل ببطء وتحكم كامل مع الحفاظ على التوتر العضلي طوال المسار السلبي."]', 'Shoulders',
      'الأكتاف', 'Shoulders', 'Dumbbell',
      'دمبلز', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/shoulders-dumbbells-overhead-press.gif', 'https://musclewiki.com/media/uploads/shoulders-dumbbells-overhead-press.gif',
      'https://musclewiki.com/media/uploads/shoulders-dumbbells-overhead-press.gif', 'https://www.youtube.com/results?search_query=RG%20Forward-Leaning%20Dumbbell%20Upright%20Row%20tutorial%20form', 'https://www.youtube.com/results?search_query=RG%20Forward-Leaning%20Dumbbell%20Upright%20Row%20tutorial%20form',
      '', '["Triceps Brachii"," Upper Chest"," Trapezius"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
