    ) VALUES (
      2668, 'Alternating Cable Shoulder Press', 'Alternating Cable Shoulder Press', 'ضغط أكتاف علوي بالتبادل بالكيبل',
      'Master guide and execution tutorial for Alternating Cable Shoulder Press.', 'Master guide and execution tutorial for Alternating Cable Shoulder Press.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين ضغط أكتاف علوي بالتبادل بالكيبل.',
      '["Move the cables to the bottom of the tower and select an appropriate weight.","Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.","Keeping your head and chest up, extend through the elbow to press one side directly over head.","After pausing at the top, return to the starting position and repeat on the opposite side."]', '["قف أو اجلس باستقامة تامة مع شد عضلات الجذع لتنفيذ ضغط أكتاف علوي بالتبادل بالكيبل.","ارفع المقاومة بالمسار المخصص مع إبقاء الأكتاف منخفضة وبعيدة عن الرقبة.","توقف لجزء من الثانية في قمة الحركة لعزل الرأس المستهدف من الدالية.","انزل ببطء وتحكم كامل مع الحفاظ على التوتر العضلي طوال المسار السلبي."]', 'Shoulders',
      'الأكتاف', 'Shoulders', 'Cable',
      'كيبل', 'Beginner', 'strength',
      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Cable_Shoulder_Press/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Cable_Shoulder_Press/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Alternating%20Cable%20Shoulder%20Press%20tutorial%20form', 'https://www.youtube.com/results?search_query=Alternating%20Cable%20Shoulder%20Press%20tutorial%20form',
      '', '["triceps"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
