    ) VALUES (
      2875, 'HM Chair Dip', 'HM Chair Dip', 'تمرين المتوازي (دبس)',
      'Master guide and execution tutorial for HM Chair Dip.', 'Master guide and execution tutorial for HM Chair Dip.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين المتوازي (دبس).',
      '["Setup: Secure your position with elbows fixed in place and core engaged, gripping the Body only","Extension: Exhale and extend your elbows, contracting the triceps until arms are fully straightened","Squeeze: Pause for a moment to maximize tension on the lateral and long heads of the triceps","Return: Inhale and allow the weight to return under strict control until elbows are flexed to 90 degrees"]', '["ثبّت الكوعين بجانب الجسم تماماً وحافظ على استقامة المعصم لأداء تمرين المتوازي (دبس).","قم بثني أو مد الذراعين بالمسار الكامل للحركة مع التركيز على انقباض العضلة.","اعصر العضلة بقوة لمدة ثانية كاملة في قمة الانقباض مع الزفير.","ارجع بالوزن ببطء خلال 3 ثوانٍ لتحقيق أقصى تمدد عضلي مفيد."]', 'Triceps',
      'الترايسبس', 'Triceps', 'Body only',
      'أدوات الجيم', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/triceps-dumbbell-overhead-extension.gif', 'https://musclewiki.com/media/uploads/triceps-dumbbell-overhead-extension.gif',
      'https://musclewiki.com/media/uploads/triceps-dumbbell-overhead-extension.gif', 'https://www.youtube.com/results?search_query=HM%20Chair%20Dip%20tutorial%20form', 'https://www.youtube.com/results?search_query=HM%20Chair%20Dip%20tutorial%20form',
      '', '["Anconeus"," Rear Delts"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
