    ) VALUES (
      2932, 'Bodyweight Mid Row', 'Bodyweight Mid Row', 'تجديف للظهر (رو) بوزن الجسم',
      'Master guide and execution tutorial for Bodyweight Mid Row.', 'Master guide and execution tutorial for Bodyweight Mid Row.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تجديف للظهر (رو) بوزن الجسم.',
      '["Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position.","Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus.","After a brief pause, return to the starting position."]', '["ثبّت الصدر للأمام والظهر مستقيماً لبدء تجديف للظهر (رو) بوزن الجسم بثبات تام للحوض.","ابدأ حركة السحب بقيادة الكوعين للخلف باتجاه الخصر وليس بسحب المعصم.","اعصر عضلات الظهر بقوة لمدة ثانية في ذروة الانقباض العضلي مع الزفير.","أعد المقاومة ببطء إلى وضعية البداية مع تمديد عضلات الظهر تدريجياً دون تقويس العمود الفقري."]', 'Back',
      'الظهر', 'Back', 'other',
      'أدوات الجيم', 'Beginner', 'strength',
      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Mid_Row/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Mid_Row/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Bodyweight%20Mid%20Row%20tutorial%20form', 'https://www.youtube.com/results?search_query=Bodyweight%20Mid%20Row%20tutorial%20form',
      '', '["biceps","lats"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
