    ) VALUES (
      2949, 'Car Drivers', 'Car Drivers', 'تمرين الأكتاف بالبار',
      'Master guide and execution tutorial for Car Drivers.', 'Master guide and execution tutorial for Car Drivers.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين الأكتاف بالبار.',
      '["While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.","Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side.","Reverse the motion, turning it all the way to the opposite side.","Repeat for the recommended amount of repetitions."]', '["قف أو اجلس باستقامة تامة مع شد عضلات الجذع لتنفيذ تمرين الأكتاف بالبار.","ارفع المقاومة بالمسار المخصص مع إبقاء الأكتاف منخفضة وبعيدة عن الرقبة.","توقف لجزء من الثانية في قمة الحركة لعزل الرأس المستهدف من الدالية.","انزل ببطء وتحكم كامل مع الحفاظ على التوتر العضلي طوال المسار السلبي."]', 'Shoulders',
      'الأكتاف', 'Shoulders', 'Barbell',
      'بار', 'Beginner', 'strength',
      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Car_Drivers/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Car_Drivers/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Car%20Drivers%20tutorial%20form', 'https://www.youtube.com/results?search_query=Car%20Drivers%20tutorial%20form',
      '', '["forearms"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
      "name" = EXCLUDED."name",
