    ) VALUES (
      3039, 'Kneeling High Pulley Row', 'Kneeling High Pulley Row', 'تجديف للظهر (رو) بالكيبل',
      'Master guide and execution tutorial for Kneeling High Pulley Row.', 'Master guide and execution tutorial for Kneeling High Pulley Row.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تجديف للظهر (رو) بالكيبل.',
      '["Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position.","Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out.","After pausing briefly, slowly return to the starting position."]', '["ثبّت الصدر للأمام والظهر مستقيماً لبدء تجديف للظهر (رو) بالكيبل بثبات تام للحوض.","ابدأ حركة السحب بقيادة الكوعين للخلف باتجاه الخصر وليس بسحب المعصم.","اعصر عضلات الظهر بقوة لمدة ثانية في ذروة الانقباض العضلي مع الزفير.","أعد المقاومة ببطء إلى وضعية البداية مع تمديد عضلات الظهر تدريجياً دون تقويس العمود الفقري."]', 'Back',
      'الظهر', 'Back', 'Cable',
      'كيبل', 'Beginner', 'strength',
      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_High_Pulley_Row/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_High_Pulley_Row/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Kneeling%20High%20Pulley%20Row%20tutorial%20form', 'https://www.youtube.com/results?search_query=Kneeling%20High%20Pulley%20Row%20tutorial%20form',
      '', '["biceps","middle back"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
