    ) VALUES (
      3083, 'Overhead Slam', 'Overhead Slam', 'تمرين الظهر',
      'Master guide and execution tutorial for Overhead Slam.', 'Master guide and execution tutorial for Overhead Slam.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين الظهر.',
      '["Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.","Initiate the countermovement by raising the ball above your head and fully extending your body.","Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.","Receive the ball with both hands on the bounce and repeat the movement."]', '["ثبّت الصدر للأمام والظهر مستقيماً لبدء تمرين الظهر بثبات تام للحوض.","ابدأ حركة السحب بقيادة الكوعين للخلف باتجاه الخصر وليس بسحب المعصم.","اعصر عضلات الظهر بقوة لمدة ثانية في ذروة الانقباض العضلي مع الزفير.","أعد المقاومة ببطء إلى وضعية البداية مع تمديد عضلات الظهر تدريجياً دون تقويس العمود الفقري."]', 'Back',
      'الظهر', 'Back', 'medicine ball',
      'أدوات الجيم', 'Beginner', 'plyometrics',
      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Slam/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Slam/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Overhead%20Slam%20tutorial%20form', 'https://www.youtube.com/results?search_query=Overhead%20Slam%20tutorial%20form',
      '', '[]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
