    ) VALUES (
      3128, 'Side to Side Box Shuffle', 'Side to Side Box Shuffle', 'تمرين الفخذ الأمامي (الكوادس)',
      'Master guide and execution tutorial for Side to Side Box Shuffle.', 'Master guide and execution tutorial for Side to Side Box Shuffle.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين الفخذ الأمامي (الكوادس).',
      '["Stand to one side of the box with your left foot resting on the middle of it.","To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement.","Continue shuffling back and forth across the box."]', '["قف مع مباعدة القدمين باتساع مناسب وثبّت الكعبين على الأرض لأداء تمرين الفخذ الأمامي (الكوادس).","انزل بالحوض للأسفل والخلف مع الحفاظ على استقامة الظهر وعضلات البطن مشدودة.","ادفع الأرض بقوة عبر باطن القدم للعودة للأعلى مع الزفير وعصر عضلات الفخذ والأرداف.","كرر الحركة بتحكم وسلاسة وتجنب قفل مفاصل الركبة بعنف في قمة الحركة."]', 'Quadriceps',
      'الفخذ الأمامي (الكوادس)', 'Quadriceps', 'other',
      'أدوات الجيم', 'Beginner', 'plyometrics',
      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_to_Side_Box_Shuffle/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_to_Side_Box_Shuffle/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Side%20to%20Side%20Box%20Shuffle%20tutorial%20form', 'https://www.youtube.com/results?search_query=Side%20to%20Side%20Box%20Shuffle%20tutorial%20form',
      '', '["abductors","adductors","calves","hamstrings"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
