    ) VALUES (
      3145, 'Spell Caster', 'Spell Caster', 'تمرين البطن والجذع بالدمبلز',
      'Master guide and execution tutorial for Spell Caster.', 'Master guide and execution tutorial for Spell Caster.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين البطن والجذع بالدمبلز.',
      '["Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position.","Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso.","Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side.","Continue alternating, rotating from one side to the other until the set is complete."]', '["اتخذ وضعية الانطلاق الصحيحة لتمرين تمرين البطن والجذع بالدمبلز مع شد عضلات الكور.","قم بالحركة بالمدى الحركي الكامل وبتحكم وسيطرة تامة على المسار.","توقف في قمة الانقباض لتركيز الجهد على العضلة المستهدفة مع الزفير.","عد ببطء إلى نقطة البداية مع الحفاظ على استقامة العمود الفقري."]', 'Abs',
      'عضلات البطن والكور', 'Abs', 'Dumbbell',
      'دمبلز', 'Beginner', 'strength',
      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spell_Caster/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spell_Caster/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Spell%20Caster%20tutorial%20form', 'https://www.youtube.com/results?search_query=Spell%20Caster%20tutorial%20form',
      '', '["glutes","shoulders"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
