    ) VALUES (
      3442, 'Wger Exercise Cardio 4d5decb3', 'Wger Exercise Cardio 4d5decb3', 'تمرين عضلات الجسم بوزن الجسم',
      'Master guide and execution tutorial for Wger Exercise Cardio 4d5decb3.', 'Master guide and execution tutorial for Wger Exercise Cardio 4d5decb3.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين عضلات الجسم بوزن الجسم.',
      '["Setup: Begin in a ready athletic stance, core braced, and breathing rhythmically","Execution: Perform dynamic, coordinated movements maintaining steady cadence and good posture","Landing: Land softly on the balls of your feet to absorb impact smoothly","Pacing: Keep an elevated heart rate while maintaining controlled breathing and full range of motion"]', '["اتخذ وضعية الانطلاق الصحيحة لتمرين تمرين عضلات الجسم بوزن الجسم مع شد عضلات الكور.","قم بالحركة بالمدى الحركي الكامل وبتحكم وسيطرة تامة على المسار.","توقف في قمة الانقباض لتركيز الجهد على العضلة المستهدفة مع الزفير.","عد ببطء إلى نقطة البداية مع الحفاظ على استقامة العمود الفقري."]', 'Full Body',
      'كامل الجسم', 'Full Body', 'Bodyweight',
      'وزن الجسم', 'Beginner', 'CARDIO',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/chest-push-ups.gif', 'https://musclewiki.com/media/uploads/chest-push-ups.gif',
      'https://musclewiki.com/media/uploads/chest-push-ups.gif', 'https://www.youtube.com/results?search_query=Wger%20Exercise%20Cardio%204d5decb3%20tutorial%20form', 'https://www.youtube.com/results?search_query=Wger%20Exercise%20Cardio%204d5decb3%20tutorial%20form',
      '', '["Stabilizer Core Muscles"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
