    ) VALUES (
      4118, 'Band standing concentration curl', 'Band standing concentration curl', 'كيرل بايسبس تركيز واقفاً بحبل المقاومة',
      'Master guide and execution tutorial for Band standing concentration curl.', 'Master guide and execution tutorial for Band standing concentration curl.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين كيرل بايسبس تركيز واقفاً بحبل المقاومة.',
      '["Setup: Stand or sit with your elbows tucked close to your torso and palms facing forward holding the Bands","Curl: While keeping upper arms stationary, exhale and curl the weights up by contracting your biceps","Peak: Squeeze at the top of the movement when your biceps are fully shortened","Lower: Inhale and slowly lower the weights back to the starting position with full extension"]', '["ثبّت الكوعين بجانب الجسم تماماً وحافظ على استقامة المعصم لأداء كيرل بايسبس تركيز واقفاً بحبل المقاومة.","قم بثني أو مد الذراعين بالمسار الكامل للحركة مع التركيز على انقباض العضلة.","اعصر العضلة بقوة لمدة ثانية كاملة في قمة الانقباض مع الزفير.","ارجع بالوزن ببطء خلال 3 ثوانٍ لتحقيق أقصى تمدد عضلي مفيد."]', 'Biceps',
      'البايسبس', 'Biceps', 'Bands',
      'حبال مقاومة', 'Beginner', 'STRENGTH',
      4.8, 'BeastMode-Enriched-Baseline', 'https://musclewiki.com/media/uploads/biceps-barbell-curl.gif', 'https://musclewiki.com/media/uploads/biceps-barbell-curl.gif',
      'https://musclewiki.com/media/uploads/biceps-barbell-curl.gif', 'https://www.youtube.com/results?search_query=Band%20standing%20concentration%20curl%20tutorial%20form', 'https://www.youtube.com/results?search_query=Band%20standing%20concentration%20curl%20tutorial%20form',
      '', '["Brachialis"," Forearms"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
