    ) VALUES (
      4142, 'Frog Hops', 'Frog Hops', 'تمرين الفخذ الأمامي (الكوادس) بوزن الجسم',
      'Master guide and execution tutorial for Frog Hops.', 'Master guide and execution tutorial for Frog Hops.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين الفخذ الأمامي (الكوادس) بوزن الجسم.',
      '["Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.","Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times."]', '["قف مع مباعدة القدمين باتساع مناسب وثبّت الكعبين على الأرض لأداء تمرين الفخذ الأمامي (الكوادس) بوزن الجسم.","انزل بالحوض للأسفل والخلف مع الحفاظ على استقامة الظهر وعضلات البطن مشدودة.","ادفع الأرض بقوة عبر باطن القدم للعودة للأعلى مع الزفير وعصر عضلات الفخذ والأرداف.","كرر الحركة بتحكم وسلاسة وتجنب قفل مفاصل الركبة بعنف في قمة الحركة."]', 'Quadriceps',
      'الفخذ الأمامي (الكوادس)', 'Quadriceps', 'Bodyweight',
      'وزن الجسم', 'Beginner', 'stretching',
      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Frog_Hops/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Frog_Hops/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Frog%20Hops%20tutorial%20form', 'https://www.youtube.com/results?search_query=Frog%20Hops%20tutorial%20form',
      '', '["calves","glutes","hamstrings"]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
