    ) VALUES (
      4212, 'Standing Hip Flexors', 'Standing Hip Flexors', 'تمرين الفخذ الأمامي (الكوادس) واقفاً بوزن الجسم',
      'Master guide and execution tutorial for Standing Hip Flexors.', 'Master guide and execution tutorial for Standing Hip Flexors.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين الفخذ الأمامي (الكوادس) واقفاً بوزن الجسم.',
      '["Stand up straight with the spine vertical, the left foot slightly in front of the right.","Bend both knees and lift the back heel off the floor as you press the right hip forward. You can''t get a thorough, deep stretch in this position, however, because it''s hard to relax the hip flexor and stand on it at the same time. Switch sides."]', '["قف مع مباعدة القدمين باتساع مناسب وثبّت الكعبين على الأرض لأداء تمرين الفخذ الأمامي (الكوادس) واقفاً بوزن الجسم.","انزل بالحوض للأسفل والخلف مع الحفاظ على استقامة الظهر وعضلات البطن مشدودة.","ادفع الأرض بقوة عبر باطن القدم للعودة للأعلى مع الزفير وعصر عضلات الفخذ والأرداف.","كرر الحركة بتحكم وسلاسة وتجنب قفل مفاصل الركبة بعنف في قمة الحركة."]', 'Quadriceps',
      'الفخذ الأمامي (الكوادس)', 'Quadriceps', 'Bodyweight',
      'وزن الجسم', 'Beginner', 'stretching',
      4.8, 'Free-Exercise-DB', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hip_Flexors/0.jpg', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hip_Flexors/0.jpg',
      '', 'https://www.youtube.com/results?search_query=Standing%20Hip%20Flexors%20tutorial%20form', 'https://www.youtube.com/results?search_query=Standing%20Hip%20Flexors%20tutorial%20form',
      '', '[]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
