    ) VALUES (
      4236, 'Exercise', 'Exercise', 'تمرين رياضي',
      'Master guide and execution tutorial for Exercise.', 'Master guide and execution tutorial for Exercise.', 'الدليل الاحترافي وخطوات الأداء الصحيح لتمرين تمرين رياضي.',
      '["Set up with proper form and a solid stance for Exercise.","Engage your core, pull your shoulders back, and maintain a neutral spine.","Execute the movement through a full range of motion while exhaling on exertion.","Control the eccentric lowering phase over 2-3 seconds while inhaling."]', '["اتخذ وضعية الانطلاق الصحيحة لتمرين تمرين رياضي مع شد عضلات الكور.","قم بالحركة بالمدى الحركي الكامل وبتحكم وسيطرة تامة على المسار.","توقف في قمة الانقباض لتركيز الجهد على العضلة المستهدفة مع الزفير.","عد ببطء إلى نقطة البداية مع الحفاظ على استقامة العمود الفقري."]', 'Full Body',
      'كامل الجسم', 'Full Body', '3',
      'أدوات الجيم', 'Beginner', 'CALISTHENICS',
      4.7, 'wger-OpenData', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=400', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=400',
      '', 'https://www.youtube.com/results?search_query=undefined%20tutorial%20form', 'https://www.youtube.com/results?search_query=undefined%20tutorial%20form',
      '', '[]',
      '[]', '["Using excessive body momentum and swinging instead of muscle isolation.","Rushing through the eccentric phase without controlling the weight.","Sacrificing full range of motion for heavier loads."]',
      '["استخدام الزخم الحركي وأرجحة الجسم بدلاً من التركيز على عزل العضلة.","النزول السريع بدون تحكم في الوزن مما يقلل الاستفادة ويزيد فرصة الإصابة.","تقليل المدى الحركي الكامل من أجل رفع أوزان زائدة تفوق القدرة."]', CURRENT_TIMESTAMP
    ) ON CONFLICT ("id") DO UPDATE SET
      "name" = EXCLUDED."name",
      "name_en" = EXCLUDED."name_en",
      "name_ar" = EXCLUDED."name_ar",
      "description_en" = EXCLUDED."description_en",
      "description_ar" = EXCLUDED."description_ar",
      "instructions_en" = EXCLUDED."instructions_en",
      "instructions_ar" = EXCLUDED."instructions_ar",
      "muscle_en" = EXCLUDED."muscle_en",
